actions.script:
const num = v => v == null ? null : v.toNumber ? v.toNumber() : Number(v)
const find = (n, c) => Array.from(ec.entity.find(n).condition(c).disableAuthz().list())
const one = (n, c) => ec.entity.find(n).condition(c).disableAuthz().one()
base = one('moqui.agent.AgentExperiment', {experimentId: baseId})
otherOptions = []; compareRows = []; headline = ''
if (base) {
    otherOptions = find('moqui.agent.AgentExperiment', {datasetId: base.datasetId}).filter(e => e.experimentId !== baseId)
        .sort((a, b) => String(b.startedDate).localeCompare(String(a.startedDate))).map(e => ({value: e.experimentId, label: (e.experimentName || e.experimentId) + ' (' + (e.agentId || e.serviceName) + ')'}))
    if (!otherId && otherOptions.length) otherId = otherOptions[0].value
}
other = otherId ? one('moqui.agent.AgentExperiment', {experimentId: otherId}) : null
if (base && other) {
    // the item's mean over trials and scorers; items edited between versions are matched by input
    const items = {}; for (const i of find('moqui.agent.AgentDatasetItem', {datasetId: base.datasetId})) items[i.itemId] = i
    const means = e => { const m = {}; for (const s of find('moqui.agent.AgentScore', {experimentId: e.experimentId})) { if (s.score == null) continue; const key = items[s.itemId]?.inputText || s.itemId; const v = m[key] = m[key] || {n: 0, sum: 0}; v.n++; v.sum += num(s.score) } return m }
    const a = means(base), b = means(other), keys = [...new Set([...Object.keys(a), ...Object.keys(b)])]
    const mean = v => v ? v.sum / v.n : null
    compareRows = keys.map(k => { const x = mean(a[k]), y = mean(b[k]); return {input: k.length > 200 ? k.slice(0, 200) + '…' : k, base: x == null ? '' : x.toFixed(2), other: y == null ? '' : y.toFixed(2),
        delta: x == null || y == null ? '' : (y - x >= 0 ? '+' : '') + (y - x).toFixed(2), change: x == null || y == null ? 'only in one' : y - x > 0.05 ? 'better' : y - x < -0.05 ? 'worse' : 'same', sortKey: x == null || y == null ? 0 : y - x} })
        .sort((p, q) => p.sortKey - q.sortKey)
    const fmt = e => (e.experimentName || e.experimentId) + ': mean ' + (e.meanScore == null ? '–' : num(e.meanScore).toFixed(2)) + ', passed ' + (e.passRate == null ? '–' : Math.round(num(e.passRate) * 100) + '%')
    headline = fmt(base) + '  →  ' + fmt(other) + ' · ' + compareRows.filter(r => r.change === 'worse').length + ' worse, ' + compareRows.filter(r => r.change === 'better').length + ' better'
}
